const entrada = items[0].json;

// Sanitização
const nome = String(entrada.nome || "")
  .replace(/\s+/g, " ")
  .trim();

// Tradução dos nomes dos campos
const labels = {
  nome_completo: "Nome completo",
  cpf: "CPF",
  nacionalidade: "Nacionalidade",
  estado_civil: "Estado civil",
  profissao: "Profissão",
  email: "E-mail",
  endereco: "Endereço completo"
};

// Campos pendentes
const camposPendentes = Array.isArray(entrada.campos_pendentes)
  ? entrada.campos_pendentes
  : [];

// Ex.: "RG, CPF e Endereço completo"
const camposFormatados = camposPendentes
  .map(campo => labels[campo] || campo)
  .join(", ");

// Preview da mensagem
const mensagemCompleta = `Olá, ${nome}! Tudo bem?

Estamos finalizando a elaboração do seu contrato, porém ainda precisamos das seguintes informações:

📋 ${camposFormatados}

Assim que recebermos esses dados, poderemos gerar e encaminhar o contrato para sua análise e assinatura.

Se tiver qualquer dúvida, estamos à disposição para ajudar.`;

const redisMemoryMessage = JSON.stringify({
  type: "ai",
  data: {
    content: mensagemCompleta,
    tool_calls: [],
    invalid_tool_calls: [],
    additional_kwargs: {},
    response_metadata: {}
  }
});

// Body WhatsApp
const body = {
  messaging_product: "whatsapp",
  to: String(entrada.telefone),
  type: "template",
  template: {
    name: "followup_dados_contrato_pendente",
    language: {
      code: "pt_BR"
    },
    components: [
      {
        type: "body",
        parameters: [
          {
            type: "text",
            text: nome
          },
          {
            type: "text",
            text: camposFormatados
          }
        ]
      }
    ]
  }
};

return [{
  json: {
    participant_id: entrada.id,
    telefone: entrada.telefone,
    nome,
    template_name: "followup_dados_contrato_pendente",
    campos_pendentes: camposPendentes,

    // Preview
    mensagem_completa: mensagemCompleta,

    // Valor pronto para gravar no Redis
    redis_memory_message: redisMemoryMessage,

    // Body WhatsApp
    resultado: body
  }
}];
